use std::fs
use std::collections::BTreeMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: BTreeMap<string, int> = BTreeMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().map(|x| x.to_string()).collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(p[1]) {
                println("error: duplicate account")
            } else {
                acc.insert(p[1], amt)
                println("ok")
            }
        } else if cmd == "balance" && p.len() >= 2 {
            match acc.get(p[1]) {
                Some(b) => println("${b}"),
                None => println("error: unknown account ${p[1]}"),
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else {
                let cur: int = acc.get(p[1]).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(p[1], cur + amt)
                    println("ok")
                } else if cur < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], cur - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let amt: int = p[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(p[1]) {
                println("error: unknown account ${p[1]}")
            } else if !acc.contains_key(p[2]) {
                println("error: unknown account ${p[2]}")
            } else if p[1] == p[2] {
                println("error: same account")
            } else {
                let a: int = acc.get(p[1]).unwrap_or(0)
                let b: int = acc.get(p[2]).unwrap_or(0)
                if a < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(p[1], a - amt)
                    acc.insert(p[2], b + amt)
                    println("ok")
                }
            }
        }
    }
    for (k, v) in acc {
        println("${k} ${v}")
    }
}

